    auto r2 = sqr(position[0], position[1], position[2]);
    r2 = sqr(position[0], position[1], position[2]);
    T const r = sqrt(r2);
    T const rinv1 = -(r > T(0)) / max(r, T(1e-20));
    T const rinv2 = -rinv1 * rinv1;
    T const rinv3 = -rinv2 * rinv1;
    T const rinv4 = -rinv2 * rinv2;
    T const rinv5 = -rinv3 * rinv2;
    T const rinv6 = -rinv3 * rinv3;
